package com.portfolio.features.experience.dto; import jakarta.validation.constraints.*; import java.time.LocalDate; public record ExperienceRequest(@NotBlank(message="Company is required.") String company,@NotBlank(message="Position is required.") String position,String location,@NotNull(message="Start date is required.") LocalDate startDate,LocalDate endDate,boolean currentlyWorking,String description,int sortOrder) { @AssertTrue(message="End date must be after start date and empty when currently working.") public boolean validDates(){return currentlyWorking ? endDate==null : endDate==null || !endDate.isBefore(startDate);} }
